) VALUES (
) ON DUPLICATE KEY UPDATE id = LAST_INSERT_ID(id), psp_bank_code = #{pspBankCode}, status = #{status}, sort = #{sort}, remark = #{remark}, updated_by = #{updatedBy}, updated_at = #{updatedAt}

